import sys
import traceback

def _test(expected, actual, call):
    try:
        assert actual == expected, f"{call} should return {expected}. Your code: {actual}"
        print(f"\u2713 passed: {call} \u2192 {expected}")
    except AssertionError as ae:
        print(f"\u2717 failed: {ae}")

class FractionTests:

    def __init__(self, module_name):
        self.module = module_name
        self.Fraction = self.module.Fraction

    def test_01_constructor_basic(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            f = self.Fraction(1, 2)
            _test("1/2", str(f), "str(Fraction(1, 2))")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_02_constructor_negative_numerator(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            f = self.Fraction(-3, 4)
            _test("-3/4", str(f), "str(Fraction(-3, 4))")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_03_constructor_denom_zero_error(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            self.Fraction(1, 0)
        except ValueError:
            print(f"\u2713 passed: Fraction(1, 0) raises ValueError")
        except Exception as e:
            print(f"\u2717 FAILED. Wrong exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

