    def test_15_comparison_equal(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            a = self.Fraction(2, 4)
            b = self.Fraction(1, 2)
            _test(True, a <= b, "Fraction(2,4) <= Fraction(1,2)")
            _test(True, a >= b, "Fraction(2,4) >= Fraction(1,2)")
        except Exception as e:
            print(f"\u2717 FAILED. Exception: {type(e).__name__}: {e}")
            print(traceback.format_exc())

    def test_all(self):
        self.test_01_constructor_basic()
        self.test_02_constructor_negative_numerator()
        self.test_03_constructor_denom_zero_error()
        self.test_04_constructor_denom_negative_error()
        self.test_05_reduce_basic()
        self.test_06_reduce_negative()
        self.test_07_addition_simple()
